"""Source of truth for the 20 baseline questions. gold_sql is T-SQL for the lakehouse SQL endpoint.
duck is the same query for DuckDB when the syntax differs (None means identical)."""
REV = "l.l_extendedprice * (1 - l.l_discount)"
Q = [
 ("Q01", "How many customers are there?",
  "SELECT COUNT(*) AS customers FROM customer;", None),
 ("Q02", "How many orders were placed in 1996?",
  "SELECT COUNT(*) AS orders_1996 FROM orders WHERE o_orderdate >= '1996-01-01' AND o_orderdate < '1997-01-01';", None),
 ("Q03", "How many suppliers are based in Germany?",
  "SELECT COUNT(*) AS suppliers FROM supplier s JOIN nation n ON s.s_nationkey = n.n_nationkey WHERE n.n_name = 'GERMANY';", None),
 ("Q04", "How many line items were shipped by air (ship mode AIR)?",
  "SELECT COUNT(*) AS air_lines FROM lineitem WHERE l_shipmode = 'AIR';", None),
 ("Q05", "What is the average account balance of customers in the BUILDING market segment? Round to 2 decimals.",
  "SELECT CAST(ROUND(AVG(CAST(c_acctbal AS DECIMAL(18,4))), 2) AS DECIMAL(18,2)) AS avg_acctbal FROM customer WHERE c_mktsegment = 'BUILDING';", None),
 ("Q06", "How many customers are in each market segment?",
  "SELECT c_mktsegment, COUNT(*) AS customers FROM customer GROUP BY c_mktsegment ORDER BY c_mktsegment;", None),
 ("Q07", "How many orders were placed in 1997 for each order priority?",
  "SELECT o_orderpriority, COUNT(*) AS orders FROM orders WHERE o_orderdate >= '1997-01-01' AND o_orderdate < '1998-01-01' GROUP BY o_orderpriority ORDER BY o_orderpriority;", None),
 ("Q08", "What was the total quantity shipped per ship mode for line items shipped in 1998?",
  "SELECT l_shipmode, SUM(l_quantity) AS total_qty FROM lineitem WHERE l_shipdate >= '1998-01-01' AND l_shipdate < '1999-01-01' GROUP BY l_shipmode ORDER BY l_shipmode;", None),
 ("Q09", "Which region has the most customers, and how many?",
  "SELECT TOP 1 r.r_name, COUNT(*) AS customers FROM customer c JOIN nation n ON c.c_nationkey = n.n_nationkey JOIN region r ON n.n_regionkey = r.r_regionkey GROUP BY r.r_name ORDER BY customers DESC;",
  "SELECT r.r_name, COUNT(*) AS customers FROM customer c JOIN nation n ON c.c_nationkey = n.n_nationkey JOIN region r ON n.n_regionkey = r.r_regionkey GROUP BY r.r_name ORDER BY customers DESC LIMIT 1;"),
 ("Q10", "List the top 3 nations by number of suppliers.",
  "SELECT TOP 3 n.n_name, COUNT(*) AS suppliers FROM supplier s JOIN nation n ON s.s_nationkey = n.n_nationkey GROUP BY n.n_name ORDER BY suppliers DESC;",
  "SELECT n.n_name, COUNT(*) AS suppliers FROM supplier s JOIN nation n ON s.s_nationkey = n.n_nationkey GROUP BY n.n_name ORDER BY suppliers DESC LIMIT 3;"),
 ("Q11", "What was the total revenue (extended price times one minus discount) for orders placed from January 1 to March 31, 1994?",
  f"SELECT CAST(SUM({REV}) AS DECIMAL(18,2)) AS revenue FROM orders o JOIN lineitem l ON l.l_orderkey = o.o_orderkey WHERE o.o_orderdate >= '1994-01-01' AND o.o_orderdate < '1994-04-01';", None),
 ("Q12", "Who are the top 5 customers by total revenue (extended price times one minus discount) across all orders?",
  f"SELECT TOP 5 c.c_name, CAST(SUM({REV}) AS DECIMAL(18,2)) AS revenue FROM customer c JOIN orders o ON o.o_custkey = c.c_custkey JOIN lineitem l ON l.l_orderkey = o.o_orderkey GROUP BY c.c_name ORDER BY revenue DESC;",
  f"SELECT c.c_name, CAST(SUM({REV}) AS DECIMAL(18,2)) AS revenue FROM customer c JOIN orders o ON o.o_custkey = c.c_custkey JOIN lineitem l ON l.l_orderkey = o.o_orderkey GROUP BY c.c_name ORDER BY revenue DESC LIMIT 5;"),
 ("Q13", "What percentage of line items have return flag R? Round to 2 decimals.",
  "SELECT CAST(ROUND(100.0 * SUM(CASE WHEN l_returnflag = 'R' THEN 1 ELSE 0 END) / COUNT(*), 2) AS DECIMAL(9,2)) AS pct_returned FROM lineitem;", None),
 ("Q14", "What percentage of line items were received after their commit date? Round to 2 decimals.",
  "SELECT CAST(ROUND(100.0 * SUM(CASE WHEN l_receiptdate > l_commitdate THEN 1 ELSE 0 END) / COUNT(*), 2) AS DECIMAL(9,2)) AS pct_late FROM lineitem;", None),
 ("Q15", "On average, how many days pass between the order date and the ship date of a line item? Round to 2 decimals.",
  "SELECT CAST(ROUND(AVG(CAST(DATEDIFF(day, o.o_orderdate, l.l_shipdate) AS FLOAT)), 2) AS DECIMAL(9,2)) AS avg_days FROM lineitem l JOIN orders o ON l.l_orderkey = o.o_orderkey;",
  "SELECT CAST(ROUND(AVG(CAST(date_diff('day', o.o_orderdate, l.l_shipdate) AS DOUBLE)), 2) AS DECIMAL(9,2)) AS avg_days FROM lineitem l JOIN orders o ON l.l_orderkey = o.o_orderkey;"),
 ("Q16", "In 1995, which month had the most orders, and how many?",
  "SELECT TOP 1 MONTH(o_orderdate) AS order_month, COUNT(*) AS orders FROM orders WHERE o_orderdate >= '1995-01-01' AND o_orderdate < '1996-01-01' GROUP BY MONTH(o_orderdate) ORDER BY orders DESC;",
  "SELECT MONTH(o_orderdate) AS order_month, COUNT(*) AS orders FROM orders WHERE o_orderdate >= '1995-01-01' AND o_orderdate < '1996-01-01' GROUP BY MONTH(o_orderdate) ORDER BY orders DESC LIMIT 1;"),
 ("Q17", "Which 3 part brands had the highest revenue (extended price times one minus discount) from suppliers in the EUROPE region?",
  f"SELECT TOP 3 p.p_brand, CAST(SUM({REV}) AS DECIMAL(18,2)) AS revenue FROM lineitem l JOIN part p ON l.l_partkey = p.p_partkey JOIN supplier s ON l.l_suppkey = s.s_suppkey JOIN nation n ON s.s_nationkey = n.n_nationkey JOIN region r ON n.n_regionkey = r.r_regionkey WHERE r.r_name = 'EUROPE' GROUP BY p.p_brand ORDER BY revenue DESC;",
  f"SELECT p.p_brand, CAST(SUM({REV}) AS DECIMAL(18,2)) AS revenue FROM lineitem l JOIN part p ON l.l_partkey = p.p_partkey JOIN supplier s ON l.l_suppkey = s.s_suppkey JOIN nation n ON s.s_nationkey = n.n_nationkey JOIN region r ON n.n_regionkey = r.r_regionkey WHERE r.r_name = 'EUROPE' GROUP BY p.p_brand ORDER BY revenue DESC LIMIT 3;"),
 ("Q18", "What is the average order value (sum of extended price times one minus discount per order) for 1-URGENT orders compared with 5-LOW orders? Round to 2 decimals.",
  f"SELECT o.o_orderpriority, CAST(ROUND(AVG(v.order_value), 2) AS DECIMAL(18,2)) AS avg_order_value FROM orders o JOIN (SELECT l.l_orderkey, SUM({REV}) AS order_value FROM lineitem l GROUP BY l.l_orderkey) v ON v.l_orderkey = o.o_orderkey WHERE o.o_orderpriority IN ('1-URGENT', '5-LOW') GROUP BY o.o_orderpriority ORDER BY o.o_orderpriority;", None),
 ("Q19", "What were our total sales in 1995?",
  f"SELECT CAST(SUM({REV}) AS DECIMAL(18,2)) AS sales_1995 FROM orders o JOIN lineitem l ON l.l_orderkey = o.o_orderkey WHERE o.o_orderdate >= '1995-01-01' AND o.o_orderdate < '1996-01-01';", None),
 ("Q20", "Who is our biggest customer?",
  f"SELECT TOP 1 c.c_name, CAST(SUM({REV}) AS DECIMAL(18,2)) AS revenue FROM customer c JOIN orders o ON o.o_custkey = c.c_custkey JOIN lineitem l ON l.l_orderkey = o.o_orderkey GROUP BY c.c_name ORDER BY revenue DESC;",
  f"SELECT c.c_name, CAST(SUM({REV}) AS DECIMAL(18,2)) AS revenue FROM customer c JOIN orders o ON o.o_custkey = c.c_custkey JOIN lineitem l ON l.l_orderkey = o.o_orderkey GROUP BY c.c_name ORDER BY revenue DESC LIMIT 1;"),
]
# Documented alternative readings for the deliberately ambiguous questions (scored as "partial" if matched).
ALT = {
 "Q19": [("gross, by order date", "SELECT CAST(SUM(l.l_extendedprice) AS DECIMAL(18,2)) FROM orders o JOIN lineitem l ON l.l_orderkey = o.o_orderkey WHERE o.o_orderdate >= '1995-01-01' AND o.o_orderdate < '1996-01-01'"),
         ("net, by ship date", "SELECT CAST(SUM(l.l_extendedprice * (1 - l.l_discount)) AS DECIMAL(18,2)) FROM lineitem l WHERE l.l_shipdate >= '1995-01-01' AND l.l_shipdate < '1996-01-01'"),
         ("gross, by ship date", "SELECT CAST(SUM(l.l_extendedprice) AS DECIMAL(18,2)) FROM lineitem l WHERE l.l_shipdate >= '1995-01-01' AND l.l_shipdate < '1996-01-01'"),
         ("net incl. tax, by order date", "SELECT CAST(SUM(l.l_extendedprice * (1 - l.l_discount) * (1 + l.l_tax)) AS DECIMAL(18,2)) FROM orders o JOIN lineitem l ON l.l_orderkey = o.o_orderkey WHERE o.o_orderdate >= '1995-01-01' AND o.o_orderdate < '1996-01-01'")],
 "Q20": [("most orders", "SELECT c.c_name, COUNT(*) n FROM customer c JOIN orders o ON o.o_custkey = c.c_custkey GROUP BY c.c_name ORDER BY n DESC, c.c_name LIMIT 3"),
         ("gross revenue", "SELECT c.c_name, CAST(SUM(l.l_extendedprice) AS DECIMAL(18,2)) r FROM customer c JOIN orders o ON o.o_custkey = c.c_custkey JOIN lineitem l ON l.l_orderkey = o.o_orderkey GROUP BY c.c_name ORDER BY r DESC LIMIT 1"),
         ("highest account balance", "SELECT c_name, c_acctbal FROM customer ORDER BY c_acctbal DESC LIMIT 3")],
}
